int total_cells, start_id, end_id;
vector<int> adj[30];
int deg[30];
bool vis[30];

long long dfs(int u, int visited_cnt) {
    if (visited_cnt == total_cells - 1) {
        for (int v : adj[u]) {
            if (v == end_id) return 1;
        }
        return 0;
    }
    if (deg[end_id] == 0) return 0;

    int forced = -1;
    for (int v : adj[u]) {
        if (vis[v] || v == end_id) continue;
        if (deg[v] == 0) return 0;
        if (deg[v] == 1) {
            if (forced != -1) return 0;
            forced = v;
        }
    }

    long long ans = 0;
    auto go = [&](int v) {
        vis[v] = true;
        for (int w : adj[v]) {
            if (!vis[w]) --deg[w];
        }
        ans += dfs(v, visited_cnt + 1);
        for (int w : adj[v]) {
            if (!vis[w]) ++deg[w];
        }
        vis[v] = false;
    };

    if (forced != -1) {
        go(forced);
    } else {
        for (int v : adj[u]) {
            if (!vis[v] && v != end_id) {
                go(v);
            }
        }
    }
    return ans;
}

