def solve_case(n, k, a):
    total = sum(a)
    if total % k != 0:
        return False
    target = total // k
    a.sort(reverse=True)
    if a[0] > target:
        return False
    if k == 1:
        return True

    full_mask = (1 << n) - 1
    bad = bytearray(1 << n)

    def dfs(mask, cur):
        if mask == full_mask:
            return True
        if bad[mask]:
            return False

        if cur == 0:
            for i in range(n):
                if not (mask & (1 << i)):
                    ncur = 0 if a[i] == target else a[i]
                    if dfs(mask | (1 << i), ncur):
                        return True
                    break
            bad[mask] = 1
            return False

        prev = -1
        for i in range(n):
            if mask & (1 << i):
                continue
            v = a[i]
            if v == prev or cur + v > target:
                continue
            prev = v
            ncur = cur + v
            if ncur == target:
                ncur = 0
            if dfs(mask | (1 << i), ncur):
                return True

        bad[mask] = 1
        return False

    return dfs(0, 0)


