    if len(vals) < 81:
        return
    g = [vals[i * 9 : (i + 1) * 9] for i in range(9)]
    rmask = [0] * 9
    cmask = [0] * 9
    bmask = [0] * 9
    empties = []

    for r in range(9):
        for c in range(9):
            v = g[r][c]
            if v == 0:
                empties.append((r, c))
            else:
                bit = 1 << (v - 1)
                b = (r // 3) * 3 + (c // 3)
                rmask[r] |= bit
                cmask[c] |= bit
                bmask[b] |= bit

    n_emp = len(empties)

    def dfs(k):
        if k == n_emp:
            return True
        best_i = -1
        best_cnt = 10
        best_avail = 0
        for i in range(k, n_emp):
            r, c = empties[i]
            b = (r // 3) * 3 + (c // 3)
            avail = 0x1FF & ~(rmask[r] | cmask[c] | bmask[b])
            if avail == 0:
                return False
            cnt = avail.bit_count()
            if cnt < best_cnt:
                best_cnt = cnt
                best_i = i
                best_avail = avail
                if cnt == 1:
                    break

        empties[k], empties[best_i] = empties[best_i], empties[k]
        r, c = empties[k]
        b = (r // 3) * 3 + (c // 3)
        avail = best_avail

        while avail:
            bit = avail & -avail
            avail ^= bit
            g[r][c] = bit.bit_length()
            rmask[r] |= bit
            cmask[c] |= bit
            bmask[b] |= bit
            if dfs(k + 1):
                return True
            rmask[r] ^= bit
            cmask[c] ^= bit
            bmask[b] ^= bit
            g[r][c] = 0

        empties[k], empties[best_i] = empties[best_i], empties[k]
        return False

    dfs(0)
    print("\n".join(" ".join(map(str, row)) for row in g))


if __name__ == "__main__":
    main()

#include <bits/stdc++.h>
using namespace std;

void gen(int idx, int end_idx, long long cur, long long limit, const vector<long long>& a, vector<long long>& out) {
    if (cur > limit) return;
    if (idx == end_idx) {
        out.push_back(cur);
        return;
    }
    gen(idx + 1, end_idx, cur, limit, a, out);
    gen(idx + 1, end_idx, cur + a[idx], limit, a, out);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long s;
    if (!(cin >> n >> s)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    int mid = n / 2;
    vector<long long> L, R;
    L.reserve(1 << mid);
    R.reserve(1 << (n - mid));
    gen(0, mid, 0, s, a, L);
    gen(mid, n, 0, s, a, R);

    sort(L.begin(), L.end());
    sort(R.begin(), R.end());

    long long ans = 0;
    int i = 0, j = (int)R.size() - 1;
    while (i < (int)L.size() && j >= 0) {
        long long sum = L[i] + R[j];
        if (sum < s) {
            ++i;
        } else if (sum > s) {
            --j;
        } else {
            long long valL = L[i], valR = R[j];
            long long cntL = 0, cntR = 0;
            while (i < (int)L.size() && L[i] == valL) {
                ++cntL;
                ++i;
            }
            while (j >= 0 && R[j] == valR) {
                ++cntR;
                --j;
            }
            ans += cntL * cntR;
        }
    }

    cout << ans << '\n';
    return 0;
}
