import sys
from collections import Counter


def gen_sums(arr, limit):
    sums = [0]
    for x in arr:
        if x <= limit:
            sums += [v + x for v in sums if v + x <= limit]
    return sums


def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    n, s = data[0], data[1]
    a = data[2 : 2 + n]

    mid = n // 2
    left = gen_sums(a[:mid], s)
    right = gen_sums(a[mid:], s)

    cnt = Counter(left)
    ans = 0
    for v in right:
        need = s - v
        if need in cnt:
            ans += cnt[need]
    print(ans)


if __name__ == "__main__":
    main()
